-- Create "notify_broadcasts" table
CREATE TABLE "notify_broadcasts" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "title" character varying NOT NULL, "content" text NOT NULL, "channels" jsonb NOT NULL, "target_type" character varying NOT NULL DEFAULT 'all', "target_ids" jsonb NULL, "scheduled_at" timestamptz NULL, "status" character varying NOT NULL DEFAULT 'pending', "created_by" bigint NOT NULL, "audience" bigint NOT NULL DEFAULT 0, "sent_count" bigint NOT NULL DEFAULT 0, "failed_count" bigint NOT NULL DEFAULT 0, "started_at" timestamptz NULL, "finished_at" timestamptz NULL, PRIMARY KEY ("id"));
-- Create index "notifybroadcast_status_scheduled_at" to table: "notify_broadcasts"
CREATE INDEX "notifybroadcast_status_scheduled_at" ON "notify_broadcasts" ("status", "scheduled_at");
